response.experiment:
probes = [[], [0], [1], [2], [1, 2], [2, 1], [1, 1], [2, 3], [-1, 1], [5], [1, 2, 3], [10, -10]]
out = []
for values in probes:
    response = call("evaluate", {"values": values})
    entry = {"values": values, "status": response.get("status")}
    if response.get("status") == "ok":
        entry["result"] = response.get("result")
        entry["evidence_id"] = response.get("evidence_id")
    else:
        entry["error"] = response.get("error", response.get("result"))
    out.append(entry)
emit(out)

